import SwiftUI

struct PetView: View { @EnvironmentObject var store: AppStore; @State private var showFeed = false; @State private var showGames = false; @State private var showWardrobe = false; @State private var showInfo = false; var body: some View { ScrollView(showsIndicators: false) { VStack(spacing: 18) { ScreenHeader(icon: "flame.fill", title: store.pet.name, subtitle: "Твой верный питомец ❤", trailing: AnyView(Button { showWardrobe = true } label: { Image(systemName: "tshirt.fill").font(.title2).padding(15).background(.ultraThinMaterial, in: Circle()) })); GlassCard { ZStack { VStack(spacing: 8) { Text("\(store.pet.hat)").font(.system(size: 32)).offset(y: 18); FlamioCharacter(jacket: store.pet.jacket).frame(height: 260); Text("\(store.pet.accessory)  \(store.pet.streak) день подряд").font(.headline).foregroundStyle(.orange) }; VStack { HStack { Spacer(); VStack(spacing: 6) { Text("🔥").font(.title); Text("\(store.pet.streak)").font(.title.bold()); Text("пламя").font(.caption).foregroundStyle(.secondary); Text(store.pet.lastCare.map { $0.formatted(.dateTime.hour().minute()) } ?? "пора заботиться").font(.caption2).foregroundStyle(.purple) }.padding(12).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 20)) }.padding(.top, 20); Spacer() } }.padding(.horizontal, 22); HStack(spacing: 12) { PrimaryButton(title: "Покормить", icon: "fork.knife") { showFeed = true }; PrimaryButton(title: "Играть", icon: "gamecontroller.fill", color: [.purple, .indigo]) { showGames = true } }.padding(.horizontal, 22); GlassCard { HStack { Text(FoodKind.allCases.sorted(by: { $0.quality > $1.quality }).first?.emoji ?? "🐟").font(.largeTitle); VStack(alignment: .leading) { Text("Лучшее сейчас").font(.subheadline).foregroundStyle(.secondary); Text("Рыба или овощи").font(.title3.bold()) }; Spacer(); Image(systemName: "checkmark.seal.fill").foregroundStyle(.green) } }.padding(.horizontal, 22); history; PrimaryButton(title: "Всё о питомце", icon: "pawprint.fill", color: [.orange, .pink]) { showInfo = true }.padding(.horizontal, 22) }.padding(.bottom, 16) }.sheet(isPresented: $showFeed) { FeedView() }.sheet(isPresented: $showGames) { GameHubView() }.sheet(isPresented: $showWardrobe) { WardrobeView() }.sheet(isPresented: $showInfo) { PetInfoView() } }
    var history: some View { GlassCard { VStack(alignment: .leading, spacing: 10) { HStack { Text("Недавно").font(.headline); Spacer(); Text("Питание").font(.caption).foregroundStyle(.secondary) }; if store.pet.feeds.isEmpty { Text("История появится после первого кормления").foregroundStyle(.secondary).padding(.vertical, 10) } else { ForEach(Array(store.pet.feeds.prefix(4))) { feed in HStack { Text(feed.food.emoji); Text(feed.food.title); Spacer(); Text(feed.date.formatted(.dateTime.day().month(.abbreviated).hour().minute())).font(.caption).foregroundStyle(.secondary) } } } } }.padding(.horizontal, 22) }
}
struct FlamioCharacter: View { var jacket: String; @State private var breathe = false; var body: some View { ZStack { Circle().fill(RadialGradient(colors: [.orange.opacity(0.55), .clear], center: .center, startRadius: 10, endRadius: 155)).frame(width: 290, height: 290); Text("🔥").font(.system(size: 170)).shadow(color: .orange, radius: 20); Text("🦊").font(.system(size: 116)).offset(y: 42); Text(jacket).font(.system(size: 46)).offset(y: 30) }.scaleEffect(breathe ? 1.015 : 0.985).onAppear { withAnimation(.easeInOut(duration: 2).repeatForever(autoreverses: true)) { breathe.toggle() } } } }
struct FeedView: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; var body: some View { NavigationStack { List { Section("Выбери еду") { ForEach(FoodKind.allCases, id: \.self) { food in Button { store.addCare(food); dismiss() } label: { HStack { Text(food.emoji).font(.title2); VStack(alignment: .leading) { Text(food.title).foregroundStyle(.primary); Text(food.quality == 3 ? "Отлично для здоровья" : food.quality == 2 ? "Можно иногда" : "Только как угощение").font(.caption).foregroundStyle(food.quality > 1 ? .green : .orange) }; Spacer(); Image(systemName: "chevron.right") } } } }; Section("Правило") { Text("Старайся сочетать полезную еду и угощения. Частый фастфуд снижает настроение и бонус серии.") } }.navigationTitle("Покормить").toolbar { Button("Готово") { dismiss() } } } } }
struct WardrobeView: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; let hats = ["✨", "🎩", "👑", "🧢", "🎓"]; let jackets = ["🧥", "🥋", "🦺", "🎽", "🧣"]; let accessories = ["🔥", "💎", "⭐️", "💖", "🎀"]; var body: some View { NavigationStack { Form { Section("Образ") { Picker("Шапка", selection: $store.pet.hat) { ForEach(hats, id: \.self) { Text($0).tag($0) } }; Picker("Одежда", selection: $store.pet.jacket) { ForEach(jackets, id: \.self) { Text($0).tag($0) } }; Picker("Украшение", selection: $store.pet.accessory) { ForEach(accessories, id: \.self) { Text($0).tag($0) } } }; Section { Text("Персонаж плавно примеряет каждый предмет. Введите любой эмодзи с клавиатуры в настройках питомца.").foregroundStyle(.secondary) } }.navigationTitle("Гардероб").toolbar { Button("Готово") { dismiss() } } } } }
struct PetInfoView: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; @State private var name = ""; var body: some View { NavigationStack { List { Section("Имя") { TextField("Имя питомца", text: $name); Button("Сохранить") { store.pet.name = name } }; Section("Статистика") { LabeledContent("Серия заботы", value: "\(store.pet.streak) дней"); LabeledContent("Кормлений", value: "\(store.pet.feeds.count)"); LabeledContent("Игр", value: "\(store.pet.playMinutes) минут") }; Section("Уведомления") { Text("Напоминания о кормлении, игре и удачи перед сменой настраиваются в общих настройках.").foregroundStyle(.secondary) } }.navigationTitle("О питомце").onAppear { name = store.pet.name }.toolbar { Button("Готово") { dismiss() } } } } }

struct GameHubView: View { @EnvironmentObject var store: AppStore; @Environment(\.dismiss) var dismiss; @State private var game = 0; var body: some View { NavigationStack { VStack(spacing: 18) { Picker("Игра", selection: $game) { Text("Крестики-нолики").tag(0); Text("21").tag(1); Text("Дурак").tag(2) }.pickerStyle(.segmented); if game == 0 { TicTacToeGame() } else if game == 1 { TwentyOneGame() } else { DurakGame() }; Spacer() }.padding(20).navigationTitle("Игры с Флами").toolbar { Button("Готово") { dismiss() } } } } }
struct TicTacToeGame: View { @State private var cells = Array(repeating: "", count: 9); @State private var turn = "X"; @State private var result = "Твой ход"; var body: some View { VStack(spacing: 14) { Text(result).font(.headline); LazyVGrid(columns: Array(repeating: GridItem(.flexible()), count: 3), spacing: 8) { ForEach(0..<9, id: \.self) { i in Button { move(i) } label: { Text(cells[i]).font(.system(size: 38, weight: .bold)).frame(maxWidth: .infinity).aspectRatio(1, contentMode: .fit).background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 16)).foregroundStyle(cells[i] == "X" ? .orange : .purple) } } }; Button("Новая партия") { cells = Array(repeating: "", count: 9); turn = "X"; result = "Твой ход" }.buttonStyle(.borderedProminent) }.padding() }
    func move(_ i: Int) { guard cells[i].isEmpty, result == "Твой ход" else { return }; cells[i] = "X"; if check("X") { result = "Ты победил!"; return }; if cells.allSatisfy({ !$0.isEmpty }) { result = "Ничья"; return }; if let bot = cells.firstIndex(where: { $0.isEmpty }) { cells[bot] = "O"; result = check("O") ? "Флами победил" : "Твой ход" } }
    func check(_ s: String) -> Bool { [[0,1,2],[3,4,5],[6,7,8],[0,3,6],[1,4,7],[2,5,8],[0,4,8],[2,4,6]].contains { $0.allSatisfy { cells[$0] == s } } }
}
struct TwentyOneGame: View { @State private var player = 0; @State private var bot = 0; @State private var message = "Нажми «Карта»"; var body: some View { VStack(spacing: 18) { Text(message).font(.headline); HStack { ScorePill(title: "Ты", value: player); ScorePill(title: "Флами", value: bot) }; HStack { Button("Карта") { player += Int.random(in: 1...10); if player > 21 { message = "Перебор — Флами победил" } else if player == 21 { message = "21! Ты победил" } } .buttonStyle(.borderedProminent); Button("Стоп") { bot = Int.random(in: 16...21); message = player > bot ? "Ты победил" : "Флами победил" }.buttonStyle(.bordered) }; Button("Новая игра") { player = 0; bot = 0; message = "Нажми «Карта»" } } }
struct ScorePill: View { let title: String; let value: Int; var body: some View { VStack { Text(title).foregroundStyle(.secondary); Text("\(value)").font(.largeTitle.bold()) }.frame(maxWidth: .infinity).padding().background(.ultraThinMaterial, in: RoundedRectangle(cornerRadius: 18)) } }
struct DurakGame: View { @State private var cards = 6; @State private var message = "Начинай игру — у тебя 6 карт"; var body: some View { VStack(spacing: 18) { Text("🃏  🂠  🃁  🂡").font(.largeTitle); Text(message).multilineTextAlignment(.center); Button("Сделать ход") { if cards > 0 { cards -= 1; message = cards == 0 ? "Ты отбился! Новая раздача" : "Флами отбивает карту… карт у тебя: \(cards)" } }.buttonStyle(.borderedProminent); Button("Новая раздача") { cards = 6; message = "Начинай игру — у тебя 6 карт" }.buttonStyle(.bordered) } }
